import React, { useEffect, useState } from "react";
import Slider from "react-slick"; // react-slick 임포트
import { getDailyBoxOffice, getMovieDetail } from "../api/boxofficeApi";
import { getPosterFromTMDB } from "../api/tmdbApi";
import MovieCard from "../components/MovieCard";

// react-slick CSS 임포트
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchBoxOffice = async () => {
      setLoading(true);
      setError(null);
      try {
        const today = new Date();
        today.setDate(today.getDate() - 1);
        const targetDt = `${today.getFullYear()}${String(today.getMonth() + 1).padStart(2, "0")}${String(today.getDate()).padStart(2, "0")}`;
        const boxOfficeList = await getDailyBoxOffice(targetDt);

        const enrichedMovies = await Promise.all(
          boxOfficeList.map(async (movie, index) => {
            const detail = await getMovieDetail(movie.movieCd);
            const year = detail.openDt?.substring(0, 4) || "";
            const posterUrl = await getPosterFromTMDB(movie.movieNm, year, {
              movieNmEn: detail.movieNmEn,
              nation: detail.nations?.[0]?.nationNm,
            });

            return {
              id: movie.movieCd,
              rank: index + 1, // ⭐️ 영화 순위 정보 추가
              title: movie.movieNm,
              englishTitle: detail.movieNmEn || '',
              poster_path: posterUrl || "https://via.placeholder.com/400x600?text=No+Image",
              details: {
                'Release': detail.openDt ? `${detail.openDt.substring(0,4)}.${detail.openDt.substring(4,6)}.${detail.openDt.substring(6,8)}` : "N/A",
                'Director': detail.directors?.[0]?.peopleNm || "N/A",
                'Actors': detail.actors?.slice(0, 3).map(a => a.peopleNm).join(', ') || "N/A",
              }
            };
          })
        );
        setMovies(enrichedMovies);
      } catch (err) {
        console.error("박스오피스 데이터를 불러오는 데 실패했습니다:", err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };
    fetchBoxOffice();
  }, []);

  // ⭐️ 캐러셀 설정 객체
  const settings = {
    className: "center",
    centerMode: true, // 중앙 모드
    infinite: true, // 무한 루프
    centerPadding: "0px", // 중앙 슬라이드와의 간격
    slidesToShow: 3, // 한 번에 보여줄 슬라이드 수
    speed: 500, // 넘어가는 속도
    arrows: true, // 화살표 표시
  };

  if (loading) return <div style={styles.message}>로딩 중...</div>;
  if (error) return <div style={styles.message}>에러: {error}</div>;

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>🍿 일별 박스오피스</h1>
      {/* ⭐️ 기존 movieGrid를 Slider 컴포넌트로 교체 */}
      <div className="movie-carousel">
        <Slider {...settings}>
          {movies.map((movie) => (
            <MovieCard key={movie.id} movie={movie} rank={movie.rank} />
          ))}
        </Slider>
      </div>
    </div>
  );
}

// 스타일 객체 (기존과 유사하나 movieGrid 제거)
const styles = {
  container: {
    width: "100%",
    // maxWidth: "1200px", // 캐러셀은 화면 너비를 활용하는 것이 좋으므로 주석 처리
    margin: "0 auto",
    padding: "2rem 0", // 상하 패딩만 적용
    boxSizing: "border-box",
  },
  title: {
    fontSize: "2.5rem",
    textAlign: "center",
    marginBottom: "3rem",
    fontWeight: "bold",
  },
  message: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    height: "50vh",
    fontSize: "1.5rem",
  },
};

export default HomePage;
